var pyGrid2 = `
from PIL import Image
import numpy as np
im = Image.open('/tmp/deck/ppt/media/image6.png').convert('RGB')
a = np.array(im).astype(float)
g = a.mean(axis=2)
H,W = g.shape
colmean = g.mean(axis=0); rowmean = g.mean(axis=1)
def peaks(v, win=12):
    out=[]
    for i in range(len(v)):
        lo=max(0,i-win); hi=min(len(v),i+win+1)
        loc = np.concatenate([v[lo:max(lo,i-3)], v[min(hi,i+4):hi]])
        if len(loc)==0: continue
        if v[i] > loc.mean()+6: out.append((i, round(v[i],1), round(loc.mean(),1)))
    return out
pc = peaks(colmean); pr = peaks(rowmean)
def group(p):
    res=[];cur=[p[0]] if p else []
    for x in p[1:]:
        if x[0]-cur[-1][0]<=3: cur.append(x)
        else: res.append(cur); cur=[x]
    if cur: res.append(cur)
    return [ (int(np.mean([y[0] for y in grp])), len(grp)) for grp in res]
print('COL line candidates:', group(pc))
print('ROW line candidates:', group(pr))
`;
